#[derive(Clone, Copy)]
#[repr(C)]
struct LinuxSignalInformation {
    signal: i32,
    error: i32,
    code: i32,
    padding: i32,
    fields: [u8; 112],
}

impl LinuxSignalInformation {
    const ZERO: Self = Self {
        signal: 0,
        error: 0,
        code: 0,
        padding: 0,
        fields: [0; 112],
    };

    const fn generated(signal: u64, code: i32) -> Self {
        Self::queued(signal, code, 0)
    }

    const fn queued(signal: u64, code: i32, value: u64) -> Self {
        Self::queued_from(signal, code, value, 1, 0)
    }

    const fn queued_from(
        signal: u64,
        code: i32,
        value: u64,
        sender_pid: u32,
        sender_uid: u32,
    ) -> Self {
        let mut fields = [0; 112];
        let sender = sender_pid.to_ne_bytes();
        fields[0] = sender[0];
        fields[1] = sender[1];
        fields[2] = sender[2];
        fields[3] = sender[3];
        let sender = sender_uid.to_ne_bytes();
        fields[4] = sender[0];
        fields[5] = sender[1];
        fields[6] = sender[2];
        fields[7] = sender[3];
        let value = value.to_ne_bytes();
        fields[8] = value[0];
        fields[9] = value[1];
        fields[10] = value[2];
        fields[11] = value[3];
        fields[12] = value[4];
        fields[13] = value[5];
        fields[14] = value[6];
        fields[15] = value[7];
        Self {
            signal: signal as i32,
            error: 0,
            code,
            padding: 0,
            fields,
        }
    }

    const fn fault(signal: u64, code: i32, address: u64) -> Self {
        let mut fields = [0; 112];
        let address = address.to_ne_bytes();
        fields[0] = address[0];
        fields[1] = address[1];
        fields[2] = address[2];
        fields[3] = address[3];
        fields[4] = address[4];
        fields[5] = address[5];
        fields[6] = address[6];
        fields[7] = address[7];
        Self {
            signal: signal as i32,
            error: 0,
            code,
            padding: 0,
            fields,
        }
    }
}

