        let _ = timer::finish_linux_wait_timer();
        let _ = restore_linux_syscall(saved_msrs);
        let _ = finish_linux_thread_table();
        X86_RUNTIME.ELF_PROBE_ACTIVE.store(false, Ordering::SeqCst);
