fn runtime_result(frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let action = scheduler::yield_runtime(
        frame,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        active_fs_base(),
    );
    resume_action(action)
}

fn exit_result(caller_domain: u64, frame: *mut UserTrapFrame) -> u64 {
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let failure_policy = domain::service_failure_policy(caller_domain);
    let auxiliary_exit_status = if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        let Ok(status) = u8::try_from(frame.first_argument()) else {
            return u64::MAX - 2;
        };
        Some(status)
    } else {
        None
    };
    let service_exit = failure_policy == Some(domain::ServiceFailurePolicy::RestartManaged);
    let close_wait = if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        None
    } else {
        Some(scheduler::WaitReason::IpcReceive {
            object: 3,
            service_side: !service_exit,
            peer_domain: caller_domain,
        })
    };
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        if !crate::packet::retire_egress_producer_if_bound(caller_domain) {
            serial_write("ginux: auxiliary exit egress retirement failed\r\n");
            return u64::MAX;
        }
        if crate::packet::egress_is_empty() {
            if let Some((waiting_domain, sequence)) = scheduler::blocked_egress_waiter() {
                if domain::take_blocked_auxiliary_drain_request(waiting_domain)
                    && !scheduler::wake_egress_waiter_drained(caller_domain, sequence)
                {
                    serial_write("ginux: auxiliary exit drain wake failed\r\n");
                    return u64::MAX;
                }
            }
        }
    }
    let action = scheduler::exit_runtime(frame, USER_CODE_SELECTOR, USER_DATA_SELECTOR, close_wait);
    if matches!(action, RuntimeAction::Invalid) {
        serial_write("ginux: runtime exit scheduling failed\r\n");
        return u64::MAX;
    }
    if !domain::detach_thread(caller_domain) {
        serial_write("ginux: runtime exit thread detach failed\r\n");
        return u64::MAX;
    }
    if service_exit
        && (!ipc::retire_service(caller_domain) || !domain::retire_clean_service(caller_domain))
    {
        return u64::MAX;
    }
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        if !domain::begin_auxiliary_runtime_exit(caller_domain, auxiliary_exit_status.unwrap_or(0))
        {
            serial_write("ginux: auxiliary exit transition failed\r\n");
            return u64::MAX;
        }
        if !address_space::quiesce_auxiliary_device(caller_domain) {
            serial_write("ginux: auxiliary exit quiesce failed status: ");
            serial_write_u64(u64::from(auxiliary_exit_status.unwrap_or(0)));
            serial_write("\r\n");
            return u64::MAX;
        }
        if !address_space::activate_kernel_root_for_auxiliary(caller_domain) {
            serial_write("ginux: auxiliary exit kernel-root restoration failed\r\n");
            return u64::MAX;
        }
        if !address_space::release_auxiliary_address_space(caller_domain) {
            serial_write("ginux: auxiliary exit address-space release failed\r\n");
            return u64::MAX;
        }
        if !domain::retire_stopped_auxiliary_service(caller_domain) {
            serial_write("ginux: auxiliary exit retirement failed\r\n");
            return u64::MAX;
        }
    }
    resume_action(action)
}

extern "sysv64" fn user_fault_handler(frame: *mut UserFaultFrame) -> u64 {
    set_user_time_stamp_access(true);
    crate::cpu_time::back_from_user();
    crate::sync::kernel_entry_return_from_user();
    let result = crate::linux_profile::span(crate::linux_profile::Span::UserFault, || {
        handle_user_fault(frame)
    });
    // Back to user mode unless the fault returns to the kernel.
    if result != u64::MAX {
        crate::sync::kernel_entry_leave_to_user();
        crate::cpu_time::leave_for_user();
        set_user_time_stamp_access(linux_user_time_stamp_allowed());
    }
    result
}

fn handle_user_fault(frame: *mut UserFaultFrame) -> u64 {
    let _kernel_entry = crate::sync::kernel_entry_lock();
    // A refusal recorded before this fault is not this fault's.
    let _ = memory::take_user_frames_refused();
    let Some(frame) = (unsafe { frame.as_mut() }) else {
        return u64::MAX;
    };
    let fault_domain = scheduler::current_domain();
    let failure_policy = fault_domain.and_then(domain::service_failure_policy);
    let service_fault = failure_policy == Some(domain::ServiceFailurePolicy::RestartManaged);
    let fault_address = if frame.is_page_fault() {
        let address: u64;
        unsafe {
            asm!("mov {}, cr2", out(reg) address, options(nomem, nostack, preserves_flags));
        }
        address
    } else {
        0
    };
    let fault_metadata = frame.metadata(fault_address);
    let linux_page_fault = fault_domain.is_none()
        && frame.is_page_fault()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst);
    if linux_page_fault {
        crate::cpu_time::note(crate::cpu_time::TaskEvent::PageFault);
    }
    let resolved = |fault| {
        if linux_page_fault {
            crate::cpu_time::note(fault);
        }
        0
    };
    use crate::cpu_time::TaskEvent::{MajorFault, MinorFault};
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && refresh_linux_runtime_translation(fault_metadata)
    {
        return resolved(MinorFault);
    }
    // A page a userfaultfd context resolves: the thread waits for it.
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && linux_userfault(frame, fault_metadata)
    {
        return 0;
    }
    // Reclaim for the pages this fault allocates may page out the faulting
    // process's own pages.
    let reclaim = linux_swapon::LinuxUserFaultReclaim::enter();
    if fault_domain.is_none() && materialize_linux_cow_page(fault_metadata) {
        return resolved(MinorFault);
    }
    // A sibling thread on another CPU may have resolved this page's
    // copy-on-write (or otherwise made it writable) between the hardware
    // trap and now, having flushed only its own CPU's translation: the
    // page is writable again but this CPU still faults on a stale entry.
    // Flush it and let the instruction run again instead of killing the
    // process over a write the mapping now allows.
    if fault_domain.is_none() && linux_retry_resolved_write_fault(fault_metadata) {
        return resolved(MinorFault);
    }
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && (materialize_linux_runtime_mapping(fault_metadata)
            || materialize_linux_runtime_stack_page(fault_metadata)
            || grow_linux_runtime_stack(fault_metadata)
            || grow_linux_growsdown_area(fault_metadata)
            || linux_flip_write_execute_page(fault_metadata)
            || linux_volume_page_mkwrite(fault_metadata))
    {
        // A shared file page read back from its file is a major fault.
        let major = LINUX_FAULT_READ_FILE.swap(false, Ordering::Relaxed);
        return resolved(if major { MajorFault } else { MinorFault });
    }
    drop(reclaim);
    if fault_domain.is_some() && failure_policy.is_none() {
        serial_write("ginux: unexpected control fault vector/rip: ");
        serial_write_u64(fault_metadata.vector);
        serial_write(" ");
        serial_write_u64(fault_metadata.instruction);
        serial_write("\r\n");
    }
    // The page was the process's to touch but no memory was left for it.
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && memory::take_user_frames_refused()
    {
        if linux_light_thread_here().is_some() {
            serial_write("ginux: out of memory in a thread of process ");
            serial_write_u64(u64::from(current_linux_process_pid()));
            serial_write("\r\n");
            return fault_linux_light_thread(frame, fault_metadata, LINUX_SIGKILL);
        }
        if terminate_linux_process_out_of_memory() {
            return u64::MAX;
        }
    }
    // int3 and a debug trap raise SIGTRAP, which stops a traced process
    // for its tracer rather than ending it.
    if fault_domain.is_none()
        && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst)
        && X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        && (fault_metadata.vector == 1 || linux_user_breakpoint(frame, fault_metadata))
    {
        if linux_light_thread_here().is_some() {
            return fault_linux_light_thread(frame, fault_metadata, LINUX_SIGTRAP);
        }
        if trap_linux_user_to_signal_entry(frame) {
            return 0;
        }
    }
    if fault_domain.is_none() && X86_RUNTIME.ELF_PROBE_ACTIVE.load(Ordering::SeqCst) {
        serial_write("ginux: Linux user fault vector/error/address/rip:");
        serial_write_u64(fault_metadata.vector);
        serial_write(" ");
        serial_write_u64(fault_metadata.error);
        serial_write(" ");
        serial_write_u64(fault_metadata.address);
        serial_write(" ");
        serial_write_u64(fault_metadata.instruction);
        serial_write("\r\n");
        if fault_metadata.vector == 14 {
            let page = fault_metadata.address & !(PAGE_SIZE as u64 - 1);
            let runtime_page = address_space::current_linux_runtime_page(page);
            let process_mapping =
                linux_process::live_process_mapping(current_linux_process_pid(), page as usize);
            serial_write("ginux: Linux fault pid/page/stack-low/stack-top/brk-limit/occupied/frame/file/protection/registry-frame/cow-frame: ");
            for value in [
                u64::from(current_linux_process_pid()),
                page,
                X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst),
                X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst),
                X86_RUNTIME.ELF_PROBE_BRK_LIMIT.load(Ordering::SeqCst),
                u64::from(runtime_page.occupied),
                u64::from(runtime_page.frame.is_some()),
                u64::from(runtime_page.file),
                u64::from(runtime_page.protection),
                process_mapping.map_or(0, |mapping| mapping.frame.address()),
                address_space::current_linux_cow_page(page).map_or(0, |frame| frame.address()),
            ] {
                serial_write_u64(value);
                serial_write(" ");
            }
            serial_write("\r\n");
            if let Some(mapping) = process_mapping {
                serial_write("ginux: Linux fault registry writable/executable/shared/dontfork: ");
                for value in [
                    mapping.writable,
                    mapping.executable,
                    mapping.shared,
                    mapping.dontfork,
                ] {
                    serial_write_u64(u64::from(value));
                    serial_write(" ");
                }
                serial_write("\r\n");
            }
        }
        let context = frame.context();
        serial_write("ginux: Linux fault tid/fs: ");
        serial_write_u64(current_linux_tid().map_or(0, u64::from));
        serial_write(" ");
        serial_write_u64(active_fs_base());
        serial_write("\r\n");
        let current_thread = current_linux_thread_handle();
        serial_write(
            "ginux: Linux fault cpu/slot/generation/state/saved-rip/saved-rsp/saved-rcx/saved-r11: ",
        );
        for value in [
            current_linux_runtime_cpu_index() as u64,
            current_thread.map_or(u64::MAX, |handle| u64::from(handle.slot)),
            current_thread.map_or(0, |handle| u64::from(handle.generation)),
            current_thread.map_or(0, |handle| {
                u64::from(
                    X86_RUNTIME.LINUX_THREAD_STATES[usize::from(handle.slot)]
                        .load(Ordering::SeqCst),
                )
            }),
            current_thread.map_or(0, |handle| {
                X86_RUNTIME.LINUX_THREAD_RIPS[usize::from(handle.slot)].load(Ordering::SeqCst)
            }),
            current_thread.map_or(0, |handle| {
                X86_RUNTIME.LINUX_THREAD_RSPS[usize::from(handle.slot)].load(Ordering::SeqCst)
            }),
            current_thread.map_or(0, |handle| {
                X86_RUNTIME.LINUX_THREAD_RCXS[usize::from(handle.slot)].load(Ordering::SeqCst)
            }),
            current_thread.map_or(0, |handle| {
                X86_RUNTIME.LINUX_THREAD_R11S[usize::from(handle.slot)].load(Ordering::SeqCst)
            }),
        ] {
            serial_write_u64(value);
            serial_write(" ");
        }
        serial_write("\r\n");
        let mut instruction = [0_u8; 16];
        if copy_from_linux_user(context.rip, &mut instruction) {
            serial_write("ginux: Linux fault instruction bytes:");
            for byte in instruction {
                serial_write(" ");
                serial_write_u64(u64::from(byte));
            }
            serial_write("\r\n");
        }
        serial_write("ginux: Linux user fault rax/rbx/rcx/rdx/rdi/rsi/rsp/rbp/r12/r13/r14/r15:");
        for value in [
            context.rax,
            context.rbx,
            context.rcx,
            context.rdx,
            context.rdi,
            context.rsi,
            context.rsp,
            context.rbp,
            context.r12,
            context.r13,
            context.r14,
            context.r15,
        ] {
            serial_write(" ");
            serial_write_u64(value);
        }
        serial_write("\r\n");
        serial_write("ginux: Linux user fault r8/r9/r10/r11:");
        for value in [context.r8, context.r9, context.r10, context.r11] {
            serial_write(" ");
            serial_write_u64(value);
        }
        serial_write("\r\n");
        let mut return_address = [0_u8; size_of::<u64>()];
        if copy_from_linux_user(context.rsp, &mut return_address) {
            serial_write("ginux: Linux user fault stack return address: ");
            serial_write_u64(u64::from_ne_bytes(return_address));
            serial_write("\r\n");
        }
        // Which thread ran with which TLS, and the faulting instruction, so
        // a fault can be disassembled from the log.
        serial_write("ginux: Linux user fault pid/tid/slot/fs:");
        for value in [
            u64::from(current_linux_process_pid()),
            current_linux_tid().map_or(0, u64::from),
            u64::from(X86_RUNTIME.LINUX_CURRENT_THREAD_SLOT.load(Ordering::SeqCst)),
            active_fs_base(),
        ] {
            serial_write(" ");
            serial_write_u64(value);
        }
        let mut code = [0_u8; 16];
        if copy_from_linux_user(fault_metadata.instruction, &mut code) {
            serial_write(" code:");
            for byte in code {
                let digits = [
                    b"0123456789abcdef"[usize::from(byte >> 4)],
                    b"0123456789abcdef"[usize::from(byte & 15)],
                ];
                serial_write(" ");
                serial_write(core::str::from_utf8(&digits).unwrap_or("??"));
            }
        }
        serial_write("\r\n");
        write_linux_runtime_syscall_trace();
        if linux_light_thread_here().is_some() {
            return fault_linux_light_thread(
                frame,
                fault_metadata,
                linux_user_fault_signal(fault_metadata),
            );
        }
        if deliver_linux_fault_signal(
            frame,
            fault_metadata,
            linux_user_fault_signal(fault_metadata),
        ) {
            return 0;
        }
        if terminate_linux_process_for_fault(fault_metadata) {
            return u64::MAX;
        }
        abort_linux_signal();
        X86_RUNTIME.ELF_PROBE_ACTIVE.store(false, Ordering::SeqCst);
        return u64::MAX;
    }
    let action = scheduler::fault_runtime(
        frame,
        fault_address,
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
        fault_domain.and_then(|dead_domain| {
            (failure_policy != Some(domain::ServiceFailurePolicy::StopOnly)).then_some(
                scheduler::WaitReason::IpcReceive {
                    object: 3,
                    service_side: !service_fault,
                    peer_domain: dead_domain,
                },
            )
        }),
    );
    let Some(fault_domain) = fault_domain else {
        return u64::MAX;
    };
    if matches!(action, RuntimeAction::Invalid) || !domain::detach_thread(fault_domain) {
        return u64::MAX;
    }
    if service_fault && !scrub_service_restart_stack() {
        return u64::MAX;
    }
    if service_fault
        && (!domain::record_service_fault(fault_domain, fault_metadata)
            || !ipc::retire_service(fault_domain)
            || !domain::retire_service(fault_domain))
    {
        return u64::MAX;
    }
    if service_fault {
        match setup_service_restart(fault_domain) {
            ServiceRestartSetup::Started => {}
            ServiceRestartSetup::Unavailable => return resume_action(action),
            ServiceRestartSetup::RollbackFailed => return u64::MAX,
        }
    }
    if failure_policy == Some(domain::ServiceFailurePolicy::StopOnly) {
        serial_write("ginux: auxiliary user fault vector/error/address/rip: ");
        for value in [
            fault_metadata.vector,
            fault_metadata.error,
            fault_metadata.address,
            fault_metadata.instruction,
        ] {
            serial_write_u64(value);
            serial_write(" ");
        }
        serial_write("\r\n");
        if !domain::begin_auxiliary_runtime_fault(fault_domain, fault_metadata) {
            serial_write("ginux: auxiliary fault transition failed\r\n");
            return u64::MAX;
        }
        if !crate::packet::retire_egress_producer_if_bound(fault_domain) {
            serial_write("ginux: auxiliary fault egress retirement failed\r\n");
            return u64::MAX;
        }
        if !address_space::quiesce_faulted_auxiliary_device(fault_domain) {
            serial_write("ginux: auxiliary device quiesce failed vector/error/address/rip:");
            serial_write_u64(fault_metadata.vector);
            serial_write(" ");
            serial_write_u64(fault_metadata.error);
            serial_write(" ");
            serial_write_u64(fault_metadata.address);
            serial_write(" ");
            serial_write_u64(fault_metadata.instruction);
            serial_write("\r\n");
            return u64::MAX;
        }
        if !address_space::activate_kernel_root_for_auxiliary(fault_domain) {
            serial_write("ginux: auxiliary kernel-root restoration failed\r\n");
            return u64::MAX;
        }
        if !address_space::release_auxiliary_address_space(fault_domain) {
            serial_write("ginux: auxiliary address-space release failed\r\n");
            return u64::MAX;
        }
        if !domain::retire_stopped_auxiliary_service(fault_domain) {
            serial_write("ginux: auxiliary retirement failed\r\n");
            return u64::MAX;
        }
    }
    resume_action(action)
}

fn refresh_linux_runtime_translation(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || fault.address >= 1 << 47
    {
        return false;
    }
    address_space::refresh_current_linux_runtime_translation(
        fault.address & !(PAGE_SIZE as u64 - 1),
        fault.error & 2 != 0,
        fault.error & 16 != 0,
    )
}

fn materialize_linux_runtime_stack_page(fault: domain::FaultMetadata) -> bool {
    fault.vector == 14
        && fault.error & 1 == 0
        && fault.address < 1 << 47
        && materialize_linux_primary_stack_page(fault.address & !(PAGE_SIZE as u64 - 1))
}

fn grow_linux_runtime_stack(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || fault.address >= 1 << 47
    {
        return false;
    }
    let page = fault.address & !(PAGE_SIZE as u64 - 1);
    let low = X86_RUNTIME.ELF_PROBE_STACK_LOW.load(Ordering::SeqCst);
    let floor = X86_RUNTIME
        .ELF_PROBE_BRK_LIMIT
        .load(Ordering::SeqCst)
        .saturating_add(PAGE_SIZE as u64);
    let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
        .saturating_add(PAGE_SIZE as u64);
    if low == 0 || page < floor || page >= low || page >= end {
        return false;
    }
    let reserved = address_space::current_linux_runtime_page(page);
    if reserved.occupied
        && (reserved.frame.is_some()
            || reserved.file
            || reserved.protection & LINUX_PROT_WRITE as u8 == 0)
    {
        return false;
    }
    let Some([frame]) = memory::allocate_user_frames::<1>() else {
        return false;
    };
    if !address_space::prepare_linux_frame(frame.address(), &[])
        || address_space::install_current_linux_runtime_page(
            page,
            frame,
            LINUX_PROT_READ as u8 | LINUX_PROT_WRITE as u8,
            false,
            reserved.occupied,
        ) != Some(None)
    {
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
        return false;
    }
    X86_RUNTIME
        .ELF_PROBE_STACK_LOW
        .store(page, Ordering::SeqCst);
    if let Some(slot) = current_linux_thread_slot() {
        let end = (X86_RUNTIME.ELF_PROBE_STACK.load(Ordering::SeqCst) & !(PAGE_SIZE as u64 - 1))
            .saturating_add(PAGE_SIZE as u64);
        X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(page, Ordering::SeqCst);
        X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot]
            .store(end.saturating_sub(page), Ordering::SeqCst);
    }
    true
}

/// Linux's stack guard gap: a mapping that grows down stops this far
/// above the mapping below it (256 pages).
const LINUX_STACK_GUARD_GAP: u64 = 256 * PAGE_SIZE as u64;

/// A fault just below a mapping made with MAP_GROWSDOWN grows it down to
/// the faulting page (`linux_areas::grow_down`); the pages it gains are
/// reserved, and the access, run again, makes the one it touches. A
/// thread whose stack the mapping is gets the larger stack.
fn grow_linux_growsdown_area(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || fault.address < LINUX_FIXED_LOW_BASE
        || fault.address >= 1 << 47
        || !crate::sync::rank_available(crate::sync::LockRank::MEMORY_AREAS)
    {
        return false;
    }
    let page = fault.address & !(PAGE_SIZE as u64 - 1);
    if address_space::current_linux_runtime_page(page).occupied {
        return false;
    }
    let Some((old_start, protection)) = crate::linux_areas::grow_down(
        linux_execution_instance(),
        current_linux_process_pid(),
        page,
        LINUX_STACK_GUARD_GAP,
    ) else {
        return false;
    };
    let protection = linux_runtime_page_protection(u64::from(protection.bits())) as u8;
    for address in (page..old_start).step_by(PAGE_SIZE) {
        if !address_space::current_linux_runtime_page(address).occupied
            && address_space::reserve_current_linux_runtime_page(address, protection, false, false)
                .is_none()
        {
            return false;
        }
    }
    if let Some(slot) = current_linux_thread_slot() {
        if X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].load(Ordering::SeqCst) == old_start {
            X86_RUNTIME.LINUX_THREAD_STACK_BASES[slot].store(page, Ordering::SeqCst);
            X86_RUNTIME.LINUX_THREAD_STACK_SIZES[slot]
                .fetch_add(old_start - page, Ordering::SeqCst);
        }
    }
    true
}

/// Whether user fault `fault` is a breakpoint, int3 (or `int 3`), and if
/// so moves `frame` past it, where Linux reports the trap. Only INT 0x80
/// is a user gate here, so a user int3 reaches the kernel as a general
/// protection fault on IDT entry 3, at the instruction.
fn linux_user_breakpoint(frame: &mut UserFaultFrame, fault: domain::FaultMetadata) -> bool {
    /// A #GP error code naming IDT entry 3.
    const IDT_BREAKPOINT_ERROR: u64 = 3 << 3 | 2;
    if fault.vector == 3 {
        return true;
    }
    if fault.vector != 13 || fault.error != IDT_BREAKPOINT_ERROR {
        return false;
    }
    let mut first = [0_u8; 1];
    let mut second = [0_u8; 1];
    let length = match copy_from_linux_user(fault.instruction, &mut first).then_some(first[0]) {
        Some(0xcc) => 1,
        Some(0xcd)
            if copy_from_linux_user(fault.instruction.wrapping_add(1), &mut second)
                && second[0] == 3 =>
        {
            2
        }
        _ => return false,
    };
    frame.redirect(
        fault.instruction.wrapping_add(length),
        USER_CODE_SELECTOR,
        USER_DATA_SELECTOR,
    )
}

/// A user int3 or debug trap on the owner's path: SIGTRAP is queued for
/// the process and the thread goes to the vDSO's preemption entry, whose
/// system call delivers it with the trapping context (rip past the int3),
/// as a timer-delivered signal is: a traced process stops there for its
/// tracer, another runs its handler or ends. False when the signal cannot
/// be delivered that way (a handler is running), for the caller to end the
/// process as before.
fn trap_linux_user_to_signal_entry(frame: &mut UserFaultFrame) -> bool {
    let Some(entry) = crate::linux_elf::vdso_preempt_entry() else {
        return false;
    };
    if X86_RUNTIME.LINUX_SIGNAL_ACTIVE.load(Ordering::SeqCst) {
        return false;
    }
    let pid = current_linux_process_pid();
    let context = frame.context();
    if (entry..entry + 9).contains(&context.rip)
        || linux_queue_process_signal(pid, LINUX_SIGTRAP, LINUX_SI_KERNEL, None) != 0
        || !frame.redirect(entry, USER_CODE_SELECTOR, USER_DATA_SELECTOR)
    {
        return false;
    }
    *LINUX_PREEMPTED_CONTEXT[linux_cpu_slot()].lock() = Some(LinuxPreemptedContext {
        pid,
        general: [
            context.rax,
            context.rbx,
            context.rcx,
            context.rdx,
            context.rsi,
            context.rdi,
            context.rbp,
            context.r8,
            context.r9,
            context.r10,
            context.r11,
            context.r12,
            context.r13,
            context.r14,
            context.r15,
        ],
        rip: context.rip,
        rsp: context.rsp,
        rflags: context.rflags,
        signal: true,
    });
    true
}

fn materialize_linux_cow_page(fault: domain::FaultMetadata) -> bool {
    if fault.vector != 14 || fault.error & 3 != 3 || fault.address >= 1 << 47 {
        return false;
    }
    materialize_linux_cow_address(fault.address & !(PAGE_SIZE as u64 - 1))
}

/// A present-page write fault that the current mapping now allows: another
/// CPU made the page writable (it resolved the copy-on-write while this
/// thread was trapping) and invalidated only its own translation. This CPU
/// still holds a stale read-only entry, so flush it and retry rather than
/// treat the write as a protection violation. Returns false when the page
/// is genuinely not writable, leaving a real fault to be reported.
fn linux_retry_resolved_write_fault(fault: domain::FaultMetadata) -> bool {
    if fault.vector != 14 || fault.error & 3 != 3 || fault.address >= 1 << 47 {
        return false;
    }
    let page = fault.address & !(PAGE_SIZE as u64 - 1);
    if !address_space::current_linux_range_mapped(page, 1, true) {
        return false;
    }
    unsafe {
        asm!("invlpg [{}]", in(reg) page, options(nostack, preserves_flags));
    }
    true
}

extern "sysv64" fn kernel_linux_cow_fault_handler(error: u64, address: u64) -> u64 {
    let page = address & !(PAGE_SIZE as u64 - 1);
    let eligible = error & 3 == 3 && address < 1 << 47;
    let cow = eligible && address_space::current_linux_cow_page(page).is_some();
    let materialized = cow && materialize_linux_cow_address(page);
    if eligible && !materialized {
        serial_write("ginux: kernel Linux COW recovery failed address/cow/pid: ");
        serial_write_u64(address);
        serial_write(" ");
        serial_write_u64(u64::from(cow));
        serial_write(" ");
        serial_write_u64(u64::from(current_linux_process_pid()));
        serial_write("\r\n");
    }
    u64::from(materialized)
}

fn materialize_linux_cow_range(address: u64, length: usize) -> bool {
    let Some(end) = address.checked_add(length as u64) else {
        return false;
    };
    if length == 0 || address >= 1 << 47 || end > 1 << 47 {
        return false;
    }
    let mut page = address & !(PAGE_SIZE as u64 - 1);
    let last = (end - 1) & !(PAGE_SIZE as u64 - 1);
    loop {
        if address_space::current_linux_cow_page(page).is_some()
            && !materialize_linux_cow_address(page)
        {
            return false;
        }
        if page == last {
            return true;
        }
        page += PAGE_SIZE as u64;
    }
}

fn materialize_linux_cow_address(address: u64) -> bool {
    let Some(source) = address_space::current_linux_cow_page(address) else {
        return false;
    };
    let pid = current_linux_process_pid();
    let failed = |step: u64| {
        serial_write("ginux: copy-on-write fault failed address/pid/step: ");
        for value in [address, u64::from(pid), step] {
            serial_write_u64(value);
            serial_write(" ");
        }
        serial_write("\r\n");
        false
    };
    let Some(mapping) = linux_process::live_process_mapping(pid, address as usize)
        .filter(|mapping| mapping.frame == source && mapping.writable && !mapping.shared)
    else {
        return failed(1);
    };
    // The last mapping of a page writes it in place, as Linux reuses a page
    // whose map count has dropped to one.
    if address_space::linux_private_page_counted(source) && !memory::frame_is_shared(source) {
        return address_space::promote_current_linux_cow_page(address, source, mapping.executable)
            || failed(2);
    }
    let Some([replacement]) = memory::allocate_user_frames::<1>() else {
        return failed(3);
    };
    let copied = address_space::copy_linux_frame(source, replacement);
    let mapping_replaced = copied
        && linux_process::replace_live_process_mapping(
            pid,
            address as usize,
            source,
            replacement,
            true,
            mapping.executable,
        );
    let page_replaced = mapping_replaced
        && address_space::replace_current_linux_cow_page(
            address,
            source,
            replacement,
            mapping.executable,
        );
    if !page_replaced {
        if mapping_replaced {
            let _ = linux_process::replace_live_process_mapping(
                pid,
                address as usize,
                replacement,
                source,
                true,
                mapping.executable,
            );
        }
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[replacement]);
        return failed(4 + u64::from(copied) + u64::from(mapping_replaced));
    }
    address_space::release_linux_private_page(source) || failed(7)
}

/// The fault `materialize_linux_runtime_mapping` just resolved read its
/// page from its file (a major fault, as perf counts it); faults are
/// handled under the kernel entry lock, one at a time.
static LINUX_FAULT_READ_FILE: AtomicBool = AtomicBool::new(false);

fn materialize_linux_runtime_mapping(fault: domain::FaultMetadata) -> bool {
    if !X86_RUNTIME.LINUX_RUNTIME_MODE.load(Ordering::SeqCst)
        || fault.vector != 14
        || fault.error & 1 != 0
        || !((fault.address >= LINUX_FIXED_LOW_BASE
            && fault.address < linux_runtime_mmap_end().unwrap_or(0))
            || linux_runtime_heap_contains(fault.address))
    {
        return false;
    }
    let page_address = fault.address & !(PAGE_SIZE as u64 - 1);
    if linux_refill_shared_file_page(page_address) {
        LINUX_FAULT_READ_FILE.store(true, Ordering::Relaxed);
        return true;
    }
    let page = address_space::current_linux_runtime_page(page_address);
    if !page.occupied
        || page.frame.is_some()
        || page.file
        || page.protection == 0
        || fault.error & 2 != 0 && page.protection & LINUX_PROT_WRITE as u8 == 0
        || fault.error & 16 != 0 && page.protection & LINUX_PROT_EXEC as u8 == 0
    {
        return false;
    }
    let Some([frame]) = memory::allocate_user_frames::<1>() else {
        return false;
    };
    if !address_space::prepare_linux_frame(frame.address(), &[])
        || !address_space::materialize_current_linux_runtime_page(
            page_address,
            frame,
            page.protection,
            false,
        )
    {
        let _ = memory::scrub_and_release_frames(memory::FrameOwner::KERNEL, &[frame]);
        return false;
    }
    true
}

enum ServiceRestartSetup {
    Started,
    Unavailable,
    RollbackFailed,
}

fn setup_service_restart(fault_domain: u64) -> ServiceRestartSetup {
    let Some(replacement_domain) = domain::initialize_boot_service_restart() else {
        return ServiceRestartSetup::Unavailable;
    };
    let Some(replacement_handle) = domain::service_boot_handle() else {
        return if domain::discard_unstarted_service(replacement_domain) {
            ServiceRestartSetup::Unavailable
        } else {
            ServiceRestartSetup::RollbackFailed
        };
    };
    if !ipc::bind_service(replacement_domain) {
        return if domain::discard_unstarted_service(replacement_domain) {
            ServiceRestartSetup::Unavailable
        } else {
            ServiceRestartSetup::RollbackFailed
        };
    }
    let (Some(old_owner), Some(replacement_owner)) = (
        memory::FrameOwner::domain(fault_domain),
        memory::FrameOwner::domain(replacement_domain),
    ) else {
        return rollback_unstarted_replacement(replacement_domain, true);
    };
    if memory::transfer_frame_owner(old_owner, replacement_owner)
        != Some(address_space::USER_ADDRESS_SPACE_FRAMES)
    {
        return rollback_unstarted_replacement(replacement_domain, true);
    }
    if !domain::adopt_quarantined_service_frames(fault_domain, replacement_domain) {
        let _ = memory::transfer_frame_owner(replacement_owner, old_owner);
        return rollback_unstarted_replacement(replacement_domain, true);
    }
    if !scheduler::queue_service_restart(replacement_domain, replacement_handle) {
        return rollback_transferred_replacement(
            replacement_domain,
            fault_domain,
            old_owner,
            replacement_owner,
            false,
        );
    }
    if !timer::rearm_scheduler_preemption() {
        return rollback_transferred_replacement(
            replacement_domain,
            fault_domain,
            old_owner,
            replacement_owner,
            true,
        );
    }
    SERVICE_FRAMES_TRANSFERRED.store(true, Ordering::Release);
    ServiceRestartSetup::Started
}

fn rollback_unstarted_replacement(replacement_domain: u64, bound: bool) -> ServiceRestartSetup {
    if (!bound || ipc::rollback_service_binding(replacement_domain))
        && domain::discard_unstarted_service(replacement_domain)
    {
        ServiceRestartSetup::Unavailable
    } else {
        ServiceRestartSetup::RollbackFailed
    }
}

fn rollback_transferred_replacement(
    replacement_domain: u64,
    fault_domain: u64,
    old_owner: memory::FrameOwner,
    replacement_owner: memory::FrameOwner,
    queued: bool,
) -> ServiceRestartSetup {
    if (!queued || scheduler::rollback_service_restart(replacement_domain, fault_domain))
        && memory::transfer_frame_owner(replacement_owner, old_owner)
            == Some(address_space::USER_ADDRESS_SPACE_FRAMES)
        && domain::restore_quarantined_service_frames(fault_domain, replacement_domain)
        && ipc::rollback_service_binding(replacement_domain)
        && domain::discard_unstarted_service(replacement_domain)
    {
        ServiceRestartSetup::Unavailable
    } else {
        ServiceRestartSetup::RollbackFailed
    }
}

fn scrub_service_restart_stack() -> bool {
    const ADDRESS_MASK: u64 = 0x000f_ffff_ffff_f000;
    let Some((root, stack_top)) = scheduler::service_restart_stack_mapping() else {
        return false;
    };
    let active_root: u64;
    unsafe {
        asm!("mov {}, cr3", out(reg) active_root, options(nomem, nostack, preserves_flags));
    }
    let Some(stack_base) = stack_top.checked_sub(PAGE_SIZE as u64) else {
        return false;
    };
    if active_root & ADDRESS_MASK != root || stack_top % PAGE_SIZE as u64 != 0 || stack_base == 0 {
        return false;
    }
    let zeroes = [0_u8; 128];
    let mut observed = [0xff_u8; 128];
    let mut scrubbed = true;
    for offset in (0..PAGE_SIZE).step_by(zeroes.len()) {
        scrubbed &= unsafe {
            raw_copy_to_user(
                (stack_base as usize + offset) as *mut u8,
                zeroes.as_ptr(),
                zeroes.len(),
            ) == 0
                && raw_copy_from_user(
                    observed.as_mut_ptr(),
                    (stack_base as usize + offset) as *const u8,
                    observed.len(),
                ) == 0
        } && observed == zeroes;
        if !scrubbed {
            break;
        }
    }
    if !scrubbed {
        return false;
    }
    SERVICE_STACK_SCRUBBED.store(true, Ordering::Release);
    true
}

pub(crate) fn service_restart_stack_was_scrubbed() -> bool {
    SERVICE_STACK_SCRUBBED.load(Ordering::Acquire)
}

pub(crate) fn service_address_space_frames_were_transferred() -> bool {
    SERVICE_FRAMES_TRANSFERRED.load(Ordering::Acquire)
}

fn resume_action(action: RuntimeAction) -> u64 {
    match action {
        RuntimeAction::Resume {
            result,
            address_space_root,
            fs_base,
        } if activate_user_context(address_space_root, fs_base) => result,
        RuntimeAction::Resume { .. } => u64::MAX,
        RuntimeAction::Complete | RuntimeAction::Invalid => u64::MAX,
    }
}

pub(crate) fn active_fs_base() -> u64 {
    unsafe { read_msr(FS_BASE_MSR) }
}

pub(crate) fn verify_user_fs_base_installation() -> bool {
    let saved = active_fs_base();
    let first_installed = install_user_fs_base(0x1110);
    let second_installed = install_user_fs_base(0x2220);
    unsafe { write_msr(FS_BASE_MSR, saved) };
    first_installed && second_installed && active_fs_base() == saved
}

fn install_current_scheduler_fs_base() -> bool {
    scheduler::current_fs_base().is_some_and(install_user_fs_base)
}

fn install_user_fs_base(fs_base: u64) -> bool {
    if fs_base >= 1 << 47 {
        return false;
    }
    unsafe { write_msr(FS_BASE_MSR, fs_base) };
    active_fs_base() == fs_base
}

pub(crate) fn activate_user_context(root: u64, fs_base: u64) -> bool {
    fs_base < 1 << 47 && activate_user_root(root) && install_user_fs_base(fs_base)
}

pub(crate) fn activate_user_root(root: u64) -> bool {
    const ADDRESS_MASK: u64 = 0x000f_ffff_ffff_f000;
    if root == 0
        || root & !ADDRESS_MASK != 0
        || scheduler::current_address_space_root() != Some(root)
    {
        return false;
    }
    let Some(owner) = scheduler::current_domain().and_then(memory::FrameOwner::domain) else {
        return false;
    };
    let Some((instruction, stack)) = scheduler::current_instruction_and_stack() else {
        return false;
    };
    let Some(frames) = paging::validated_user_root_frames(root) else {
        return false;
    };
    if !frames.context_matches(instruction, stack)
        || !frames.frames_owned_by(owner)
        || frames
            .dma()
            .is_some_and(|dma| !memory::frame_addresses_owned_by(owner, &[dma]))
    {
        return false;
    }
    let active: u64;
    super::smp::note_active_root(root);
    unsafe {
        asm!("mov cr3, {}", in(reg) root, options(nostack, preserves_flags));
        asm!("mov {}, cr3", out(reg) active, options(nomem, nostack, preserves_flags));
    }
    super::smp::note_root_loaded();
    active & ADDRESS_MASK == root
}

unsafe fn read_msr(msr: u32) -> u64 {
    let low: u32;
    let high: u32;
    asm!("rdmsr", in("ecx") msr, out("eax") low, out("edx") high, options(nomem, nostack, preserves_flags));
    (u64::from(high) << 32) | u64::from(low)
}

unsafe fn write_msr(msr: u32, value: u64) {
    asm!("wrmsr", in("ecx") msr, in("eax") value as u32, in("edx") (value >> 32) as u32, options(nomem, nostack, preserves_flags));
}

/// Set while a fatal kernel exception is being reported, so a fault in the
/// report itself prints one line instead of recursing into a triple fault.
static FATAL_EXCEPTION_ACTIVE: AtomicBool = AtomicBool::new(false);

/// Writes `label` and `value` in hex straight to the UART and framebuffer,
/// bypassing the domain console path, which may itself be what faulted.
fn fatal_write_hex(label: &str, value: u64) {
    let mut text = [0_u8; 18];
    text[0] = b'0';
    text[1] = b'x';
    for (index, digit) in text[2..].iter_mut().enumerate() {
        let nibble = (value >> ((15 - index) * 4)) & 0xf;
        *digit = b"0123456789abcdef"[nibble as usize];
    }
    crate::serial_write_raw(label.as_bytes());
    crate::serial_write_raw(&text);
}

/// Reports a fatal kernel exception: the vector and fault details, every
/// saved register, control registers, kernel return addresses found on the
/// interrupted stack (with the image base, for symbolizing them), and then
/// the Linux state, which is read last since it is the likeliest to fault.
extern "sysv64" fn fatal_exception_handler(
    vector: u64,
    error: u64,
    fault_address: u64,
    instruction: u64,
    frame: *const u64,
) -> ! {
    if FATAL_EXCEPTION_ACTIVE.swap(true, Ordering::SeqCst) {
        fatal_write_hex("\r\nginux: nested fatal exception vector ", vector);
        fatal_write_hex(" at ", instruction);
        crate::serial_write_raw(b"\r\nGINUX_KERNEL_PANIC\r\n");
        loop {
            core::hint::spin_loop();
        }
    }
    const REGISTERS: [&str; 15] = [
        "r15", "r14", "r13", "r12", "r11", "r10", "r9", "r8", "rbp", "rdi", "rsi", "rdx", "rcx",
        "rbx", "rax",
    ];
    fatal_write_hex("\r\nginux: fatal exception vector ", vector);
    fatal_write_hex(" error ", error);
    fatal_write_hex(" rip ", instruction);
    if vector == 14 {
        fatal_write_hex(" cr2 ", fault_address);
    }
    // SAFETY: the entry stub pushed the 15 general registers, then the vector
    // and error code, and the CPU pushed rip, cs, rflags, rsp and ss.
    let saved = |index: usize| unsafe { frame.add(index).read_volatile() };
    crate::serial_write_raw(b"\r\nginux: registers");
    for (index, name) in REGISTERS.iter().enumerate() {
        if index % 5 == 0 {
            crate::serial_write_raw(b"\r\n ");
        }
        crate::serial_write_raw(b" ");
        fatal_write_hex(name, saved(index));
    }
    fatal_write_hex("\r\n  cs ", saved(18));
    fatal_write_hex(" rflags ", saved(19));
    fatal_write_hex(" rsp ", saved(20));
    fatal_write_hex(" ss ", saved(21));
    let (cr0, cr3, cr4): (u64, u64, u64);
    // SAFETY: reading control registers has no side effects.
    unsafe {
        asm!("mov {}, cr0", out(reg) cr0, options(nomem, nostack, preserves_flags));
        asm!("mov {}, cr3", out(reg) cr3, options(nomem, nostack, preserves_flags));
        asm!("mov {}, cr4", out(reg) cr4, options(nomem, nostack, preserves_flags));
    }
    fatal_write_hex("\r\n  cr0 ", cr0);
    fatal_write_hex(" cr2 ", fault_address);
    fatal_write_hex(" cr3 ", cr3);
    fatal_write_hex(" cr4 ", cr4);
    let (image_base, image_size) = crate::kernel_image_range();
    fatal_write_hex("\r\nginux: kernel image base ", image_base);
    fatal_write_hex(" size ", image_size);
    // Kernel-mode faults only: scan the interrupted stack for values that
    // point into the kernel image, which include the return addresses.
    let interrupted_stack = saved(20);
    if saved(18) & 3 == 0 && image_size != 0 {
        crate::serial_write_raw(b"\r\nginux: kernel addresses on stack:");
        let mut found = 0;
        // An overflow faults with rsp on the guard page; scanning then starts
        // on the first mapped page above it.
        let mut start = interrupted_stack;
        for _ in 0..2 {
            if crate::arch::x86_64::paging::kernel_address_is_mapped(start) {
                break;
            }
            start = (start | 0xfff) + 1;
        }
        for slot in 0..512_u64 {
            let address = start.wrapping_add(slot * 8);
            if !crate::arch::x86_64::paging::kernel_address_is_mapped(address) {
                break;
            }
            // SAFETY: the page holding `address` is mapped, checked above; this is a
            // kernel stack address, never a userspace one.
            let value = unsafe { core::ptr::read_volatile(address as *const u64) };
            if value > image_base && value < image_base + image_size {
                crate::serial_write_raw(b" ");
                fatal_write_hex("", value);
                found += 1;
                if found == 24 {
                    break;
                }
            }
        }
    }
    crate::serial_write_raw(b"\r\nginux: Linux snapshot/fork/pid: ");
    serial_write_u64(u64::from(
        X86_RUNTIME
            .LINUX_PROCESS_SNAPSHOT_STAGE
            .load(Ordering::SeqCst),
    ));
    serial_write(" ");
    serial_write_u64(u64::from(linux_process::live_fork_execution_stage()));
    serial_write(" ");
    serial_write_u64(u64::from(current_linux_process_pid()));
    serial_write(" tid ");
    serial_write_u64(u64::from(current_linux_tid().unwrap_or(0)));
    crate::serial_write_raw(b"\r\n");
    write_linux_runtime_syscall_trace();
    crate::serial_write_raw(b"GINUX_KERNEL_PANIC\r\n");
    loop {
        core::hint::spin_loop();
    }
}
